def _parse(s, ncol):
    out = {}
    for item in s.split():
        k, v = item.split(":")
        vals = [float(x) if x else np.nan for x in v.split(",")]
        out[k] = (vals + [np.nan] * ncol)[:ncol]
    return out


def _interp(points, m):
    """Linear interpolation of (months_ahead, value) points at m months ahead (no extrapolation)."""
    pts = sorted((a, b) for a, b in points if not np.isnan(b))
    xs, ys = [p[0] for p in pts], [p[1] for p in pts]
    if not xs or m < xs[0] or m > xs[-1] + 3: return np.nan
    return float(np.interp(m, xs, ys))                # beyond the last point (at most 3 months): held flat


def banxico_policy_expected(index, current, h):
    """Expected policy rate h months after the end of month t, from the survey of month t-1.
    current: policy rate at the end of each month (known in real time). Returns a Series on `index`."""
    S = {pd.Timestamp(f"20{k[:2]}-{k[2:]}-01"): v for k, v in _parse(BANXICO_POLICY, 6).items()}
    out = {}
    for t in index:
        s = t - pd.DateOffset(months=1)
        if s not in S: out[t] = np.nan; continue
        q0 = (3 - s.month % 3) % 3                         # months from the survey month to the close of its quarter
        pts = [(0, current.asof(s))] + [(q0 + 3 * k, S[s][k]) for k in range(6)]
        out[t] = _interp(pts, h + 1)                      # target month t+h is h+1 months after the survey month
    return pd.Series(out).reindex(index)


def banxico_bono10_expected(index, current10, h):
    """Expected 10-year Bono M yield h months after the end of month t, from the survey of month t-1."""
    S = {pd.Timestamp(f"20{k[:2]}-{k[2:]}-01"): v for k, v in _parse(BANXICO_BONO10, 4).items()}
    out = {}
    for t in index:
        s = t - pd.DateOffset(months=1)
        if s not in S: out[t] = np.nan; continue
        m0 = 12 - s.month                                  # months from the survey month to the close of its year
        pts = [(0, current10.asof(s))] + [(m0 + 12 * k, S[s][k]) for k in range(4)]
        out[t] = _interp(pts, h + 1)
    return pd.Series(out).reindex(index)


def spf_tbond_expected(index, current_ust10, h):
    """Expected 10-year Treasury yield h months after the end of month t, from the latest SPF released by then.
    Quarterly averages are placed at the middle month of each quarter."""
    S = {}
    for k, v in _parse(SPF_TBOND, 6).items():
        y, q = k.split("q"); S[(2000 + int(y), int(q))] = v
    out = {}
    for t in index:
        # SPF for quarter q is released in the second month of the quarter (Feb, May, Aug, Nov)
        y, q = t.year, (t.month - 1) // 3 + 1
        if t.month - 3 * (q - 1) < 2: q -= 1
        if q == 0: y, q = y - 1, 4
        if (y, q) not in S: out[t] = np.nan; continue
        mid_cur = pd.Timestamp(year=y, month=3 * (q - 1) + 2, day=1)
        base = (mid_cur.year - t.year) * 12 + mid_cur.month - t.month   # months from t to the middle of the survey quarter
        pts = [(0, current_ust10.asof(t))] + [(base + 3 * k, S[(y, q)][k + 1]) for k in range(5)]
        out[t] = _interp(pts, h)
    return pd.Series(out).reindex(index)
